import bcrypt from "bcrypt";
import bcryptjs from "bcryptjs";

export function compareLoginPassword(password, hash) {
  // Use the native worker pool for hashes generated by DespacheFull. Preserve
  // bcryptjs handling of legacy prefixes and lone UTF-16 surrogates.
  if (hash.startsWith("$2b$") && password.isWellFormed()) {
    return bcrypt.compare(password, hash);
  }
  return bcryptjs.compare(password, hash);
}
